from pathlib import Path
for p in Path('.').rglob('*'):
    if p.is_file() and '.git' not in p.parts and p.suffix in {'.go','.proto','.md','.yaml','.yml','.json'}:
        try: text=p.read_text()
        except: continue
        for i,line in enumerate(text.splitlines(),1):
            if 'store.Memo' in line or 'Memo' in line:
                print(f'{p}:{i}:{line}')
